fn bits(v: i32) -> i32 {
    let mut n: i32 = 0;
    let mut x: i32 = v;
    let mut i: i32 = 0;
    while i < 16 {
        n = n + (x & 1);
        x = x >> 1;
        i = i + 1;
    }
    n
}

fn frame(t: i32) {
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut r: i32 = 0;
        while r < 12 {
            host::display::state_set(8 + r, 0);
            host::display::state_set(20 + r, 0);
            r = r + 1;
        }
        host::display::state_set(14, 1 << 8);
        host::display::state_set(2, 991);
    }
    let mut inf = [0; 12];
    let mut imm = [0; 12];
    let mut r: i32 = 0;
    while r < 12 {
        inf[r] = host::display::state_get(8 + r);
        imm[r] = host::display::state_get(20 + r);
        r = r + 1;
    }
    if t % 10 == 0 {
        let mut newi = [0; 12];
        let mut seed: i32 = host::display::state_get(2);
        r = 0;
        while r < 12 {
            let mut c: i32 = 0;
            while c < 16 {
                let bit: i32 = 1 << c;
                if (inf[r] & bit) == 0 && (imm[r] & bit) == 0 {
                    let mut n: i32 = 0;
                    if c > 0 { n = n + ((inf[r] >> (c - 1)) & 1); }
                    if c < 15 { n = n + ((inf[r] >> (c + 1)) & 1); }
                    if r > 0 { n = n + ((inf[r - 1] >> c) & 1); }
                    if r < 11 { n = n + ((inf[r + 1] >> c) & 1); }
                    if n > 0 {
                        seed = seed * 1103515245 + 12345;
                        if ((seed >> 16) & 127) < n * 45 {
                            newi[r] = newi[r] | bit;
                        }
                    }
                }
                c = c + 1;
            }
            r = r + 1;
        }
        let mut icount: i32 = 0;
        r = 0;
        while r < 12 {
            imm[r] = imm[r] | inf[r];
            inf[r] = newi[r];
            icount = icount + bits(inf[r]);
            r = r + 1;
        }
        if icount == 0 {
            r = 0;
            while r < 12 {
                imm[r] = 0;
                inf[r] = 0;
                r = r + 1;
            }
            inf[6] = 1 << 8;
        }
        r = 0;
        while r < 12 {
            host::display::state_set(8 + r, inf[r]);
            host::display::state_set(20 + r, imm[r]);
            r = r + 1;
        }
        host::display::state_set(2, seed);
    }
    host::display::clear(0x0a0a0a);
    let mut ni: i32 = 0;
    let mut nr: i32 = 0;
    r = 0;
    while r < 12 {
        let mut c: i32 = 0;
        while c < 16 {
            let mut col: i32 = 0x104020;
            if ((inf[r] >> c) & 1) == 1 { col = 0xff4030; ni = ni + 1; }
            else if ((imm[r] >> c) & 1) == 1 { col = 0x606060; nr = nr + 1; }
            host::display::fill_rect(64 + c * 24, 100 + r * 24, 22, 22, col);
            c = c + 1;
        }
        r = r + 1;
    }
    let ns: i32 = 192 - ni - nr;
    host::display::draw_string(64, 30, "S", 0x40c060, 2);
    host::display::draw_number(84, 30, ns, 0x40c060, 2);
    host::display::draw_string(180, 30, "I", 0xff4030, 2);
    host::display::draw_number(200, 30, ni, 0xff4030, 2);
    host::display::draw_string(300, 30, "R", 0x909090, 2);
    host::display::draw_number(320, 30, nr, 0x909090, 2);
    host::display::present();
}
